def _compute_batch_embed(x: torch.Tensor, num_groups: int) -> torch.Tensor:
    """Compute a normalized projection vector from the batch statistics of ``x``."""
    grouped = _reshape_to_grouped_subtokens(x, num_groups)  # (N, num_groups, subtoken_dim)
    embed = grouped.mean(dim=(0, 1))  # (subtoken_dim,)
    return _normalize_projection(embed)


